<script setup lang="ts">
import { appUrl } from '../composables/appUrl';
import ServerTable from "./ServerTable.vue";
import { computed, ref } from 'vue';
import { useForm, usePage } from '@inertiajs/vue3';
import type { SharedProps } from '../types';
import ConfirmDialog from './ConfirmDialog.vue';
import { useConfirmedMutation } from '../composables/confirmedMutation';
const confirmation = useConfirmedMutation();
const { pending: confirming } = confirmation;
export type Participant = { id: number; nama: string; nik: string | null; email: string | null; no_hp: string | null; no_wa: string | null; instansi: string | null; jabatan: string | null; status: string; sumber: string; tgl_isi: string; nomor_quotation?: string; surat_konfirmasi: string | null; surat_konfirmasi_nama: string | null; company_confirmation_id?: number; history?: { id: number; surat_konfirmasi_nama: string; alasan: string; created_date: string }[]; revisi?:number; b2b?:boolean; sudah_bayar?:boolean; konfirmasi_deadline?:string; konfirmasi_expired?:boolean; keluar_alasan?:string; refund?:{id:number;nomor:string}|null; konfirmasi_ulang?:{keputusan:string|null;catatan:string|null;tgl_isi:string|null;diproses_date:string|null}|null };
const props = defineProps<{ rows: Participant[]; manage: boolean; dataUrl?: string; filters?: Record<string,string|number>; statusFilter?: boolean }>();
const serverRows=ref<Participant[]>([]);
const listedRows=computed(()=>props.dataUrl?serverRows.value:props.rows);
const page=usePage<SharedProps>();
const processing=ref<Participant|null>(null);
const answer=useForm({revisi:0,keputusan:'pindah_jadwal',alasan:''});
const PS_LABEL:Record<string,string>={menunggu:'Menunggu',deal:'Deal',batal:'Batal',keluar:'Keluar'};
const labels:Record<string,string>={pindah_jadwal:'Pindah jadwal',batal:'Batal ikut',refund:'Refund',tidak:'Dicoret PIC'};
function process(p:Participant){processing.value=p;answer.clearErrors();answer.revisi=p.revisi||0;answer.keputusan=p.konfirmasi_ulang?.keputusan || (p.konfirmasi_expired?(p.sudah_bayar?'refund':'batal'):'pindah_jadwal');answer.alasan=p.konfirmasi_ulang?.catatan||'';}
function saveAnswer(){return confirmation.form(answer,'post',`/quotation/peserta/${processing.value?.id}/konfirmasi-ulang`,{title:`Proses konfirmasi ulang ${processing.value?.nama}?`,text:`Keputusan: ${labels[answer.keputusan] || answer.keputusan}. Perubahan Invoice/Refund mengikuti status pembayaran.`,danger:answer.keputusan!=='pindah_jadwal'},{preserveState:'errors',onSuccess:()=>{processing.value=null;}});}
const query = ref(''); const status = ref('');
const serverFilters = computed(() => ({ ...props.filters, ...(props.statusFilter ? { peserta_status: status.value || 'all' } : {}) }));
const filtered = computed(() => props.rows.filter((p) => (!status.value || p.status === status.value) && [p.nama, p.instansi, p.email, p.no_wa, p.no_hp].some((v) => (v ?? '').toLocaleLowerCase('id-ID').includes(query.value.toLocaleLowerCase('id-ID')))));
const replacing = ref<Participant | null>(null);
const form = useForm({ surat: null as File | null, alasan: '' });
function replace(p: Participant) { replacing.value = p; form.reset(); form.clearErrors(); }
function save() { return confirmation.form(form, 'post', `/quotation/peserta/${replacing.value?.id}/surat`, { title: `Ganti surat ${replacing.value?.nama}?`, text: 'Surat lama tetap tersimpan dalam riwayat.' }, { forceFormData: true, onSuccess: () => { replacing.value = null; } }); }
</script>
<template>
    <section v-if="listedRows.some(p=>p.konfirmasi_ulang || p.status==='keluar')" class="panel"><h2>Konfirmasi ulang dan peserta Keluar</h2><article v-for="p in listedRows.filter(p=>p.konfirmasi_ulang || p.status==='keluar')" :key="p.id"><h3>{{p.nama}} · {{p.status}}</h3><p>{{p.konfirmasi_ulang?.keputusan?labels[p.konfirmasi_ulang.keputusan]:'Belum konfirmasi ulang'}} · {{p.konfirmasi_ulang?.diproses_date?'Tuntas':'Menunggu keputusan / proses Sales'}}</p><p>Batas {{p.konfirmasi_deadline}}<span v-if="p.konfirmasi_expired && !p.konfirmasi_ulang?.tgl_isi"> — dianggap tidak ikut, perlu diproses Sales.</span></p><p v-if="p.keluar_alasan">{{p.keluar_alasan}}</p><p v-if="p.refund">Refund <a v-if="page.props.permissions.sales_order_refund?.includes('View')" :href="appUrl(`/sales-order/refund/${p.refund.id}`)">{{p.refund.nomor}}</a><span v-else>{{p.refund.nomor}}</span></p><button v-if="manage && p.konfirmasi_ulang && ['deal','menunggu'].includes(p.status)" type="button" @click="process(p)">Proses konfirmasi ulang</button></article></section>
    <ConfirmDialog v-if="processing" :title="`Proses konfirmasi ulang: ${processing.nama}`" :busy="answer.processing || confirming" confirm-label="Simpan keputusan" @cancel="processing=null" @confirm="saveAnswer"><p v-if="processing.b2b" class="notice">B2B: Pindah jadwal/Batal ikut/Refund berlaku per company. Dicoret PIC hanya mengeluarkan peserta terkait tanpa Refund.</p><p>{{processing.sudah_bayar?'Invoice sudah lunas: Pindah jadwal atau Refund.':'Belum lunas: Pindah jadwal atau Batal ikut. Invoice belum dibayar akan dibatalkan; peserta lain ditagih ulang.'}}</p><label>Keputusan<select v-model="answer.keputusan"><option value="pindah_jadwal">Pindah jadwal</option><option v-if="processing.sudah_bayar" value="refund">Refund</option><option v-else value="batal">Batal ikut</option><option v-if="processing.konfirmasi_ulang?.keputusan==='tidak'" value="tidak">Dicoret PIC, tanpa Refund</option></select></label><label v-if="answer.keputusan!=='pindah_jadwal'">Alasan, wajib<textarea v-model="answer.alasan" maxlength="500" required/></label><p v-else>Konfirmasi dicatat Sales; tidak memerlukan surat baru.</p><p v-for="e in answer.errors" :key="e" class="error" role="alert">{{e}}</p></ConfirmDialog>
    <div v-if="!dataUrl || statusFilter" class="filters"><label v-if="!dataUrl">Cari peserta<input v-model="query" type="search" placeholder="Nama, instansi, email, WhatsApp" /></label><label>Status<select v-model="status"><option value="">Semua</option><option v-for="s in ['menunggu', 'deal', 'batal', 'keluar']" :key="s" :value="s">{{ PS_LABEL[s] }}</option></select></label></div>
    <ServerTable v-if="dataUrl" :url="dataUrl" label="Data Peserta" :filters="serverFilters" refresh-on-visit :columns='[{"title": "No", "orderable": false}, {"title": "Peserta", "orderable": true}, {"title": "Instansi", "orderable": true}, {"title": "Kontak", "orderable": true}, {"title": "Quotation", "orderable": true}, {"title": "Masuk lewat", "orderable": true}, {"title": "Status", "orderable": true}, {"title": "Action", "orderable": false}]' @loaded="result=>serverRows=(result.data || []) as Participant[]">
<template #cell-0="{number}">{{number}}</template><template #cell-1="{row:p}"><b>{{p.nama||'—'}}</b><small>{{p.jabatan}}</small></template><template #cell-2="{row:p}">{{p.instansi}}</template><template #cell-3="{row:p}">{{p.email}}<small>{{p.no_wa || p.no_hp}}</small></template><template #cell-4="{row:p}"><span class="code">{{p.nomor_quotation}}</span></template><template #cell-5="{row:p}"><span class="tag" :class="p.sumber==='company'?'tag-b2b':'tag-public'">{{p.sumber==='company'?'Daftar PIC':'Link'}}</span><small>{{p.tgl_isi}}</small></template><template #cell-6="{row:p}"><span class="badge" :class="`st-${p.status}`">{{PS_LABEL[p.status]||p.status}}</span></template>
<template #cell-7="{row:p}"><a v-if="p.surat_konfirmasi" :href="appUrl(`/documents/confirmation/${p.id}?preview=1`)" target="_blank" rel="noopener">Lihat surat</a><a v-else-if="p.company_confirmation_id" :href="appUrl(`/documents/company-confirmation/${p.company_confirmation_id}?preview=1`)" target="_blank" rel="noopener">Lihat surat Company</a><button v-if="manage && p.surat_konfirmasi && !['keluar','batal'].includes(p.status)" type="button" @click="replace(p)">Ganti surat</button><button v-if="manage && p.konfirmasi_ulang && ['deal','menunggu'].includes(p.status)" type="button" @click="process(p)">Proses konfirmasi ulang</button><details v-if="p.history?.length"><summary>Riwayat surat</summary><p v-for="h in p.history" :key="h.id"><a :href="appUrl(`/documents/confirmation-history/${h.id}`)" target="_blank" rel="noopener">{{h.surat_konfirmasi_nama}}</a><small>{{h.alasan}} ? {{h.created_date}}</small></p></details></template>
</ServerTable><div v-else class="table-wrap"><table><caption class="sr-only">Data Peserta dari konfirmasi kehadiran</caption><thead><tr><th>Nama / Instansi</th><th>Kontak</th><th>Quotation / Status</th><th>Surat konfirmasi</th></tr></thead><tbody>
        <tr v-for="p in filtered" :key="p.id"><td>{{ p.nama }}<small>{{ p.instansi }} · {{ p.jabatan }}</small><small v-if="p.nik">NIK: {{ p.nik }}</small></td><td>{{ p.email }}<small>{{ p.no_wa || p.no_hp }}</small></td><td>{{ p.nomor_quotation }}<small>{{ p.status }} · {{ p.sumber === 'company' ? 'Daftar PIC' : 'Link' }}</small><small>{{ p.tgl_isi }}</small></td><td><template v-if="p.surat_konfirmasi"><a :href="appUrl(`/documents/confirmation/${p.id}?preview=1`)" target="_blank" rel="noopener">Lihat surat</a> · <a :href="appUrl(`/documents/confirmation/${p.id}`)">Unduh {{ p.surat_konfirmasi_nama || 'Confirmation Letter' }}</a></template><template v-else-if="p.company_confirmation_id"><a :href="appUrl(`/documents/company-confirmation/${p.company_confirmation_id}?preview=1`)" target="_blank" rel="noopener">Lihat surat Company</a> · <a :href="appUrl(`/documents/company-confirmation/${p.company_confirmation_id}`)">Unduh</a></template><span v-else>Belum tersedia</span><button v-if="manage && p.surat_konfirmasi && !['keluar','batal'].includes(p.status)" type="button" @click="replace(p)">Ganti surat</button><details v-if="p.history?.length"><summary>Riwayat surat ({{ p.history.length }})</summary><p v-for="h in p.history" :key="h.id"><a :href="appUrl(`/documents/confirmation-history/${h.id}`)" target="_blank" rel="noopener">{{ h.surat_konfirmasi_nama }}</a><small>{{ h.alasan }} · {{ h.created_date }}</small></p></details></td></tr>
        <tr v-if="!filtered.length"><td colspan="4" class="empty">Tidak ada peserta yang cocok. Ubah filter status atau kata pencarian. Peserta masuk lewat link Konfirmasi Kehadiran.</td></tr>
    </tbody></table></div>
    <ConfirmDialog v-if="replacing" :title="`Ganti surat ${replacing.nama}`" confirm-label="Simpan pengganti" :busy="form.processing || confirming" @cancel="replacing = null" @confirm="save"><p>Surat lama tetap tersimpan dalam riwayat.</p><label>Berkas PDF/JPG/PNG, maksimal 5 MB<input type="file" accept=".pdf,.jpg,.jpeg,.png" @change="form.surat = ($event.target as HTMLInputElement).files?.[0] ?? null" /></label><label>Alasan<input v-model="form.alasan" maxlength="200" required /></label><p v-for="e in form.errors" :key="e" class="error" role="alert">{{ e }}</p></ConfirmDialog>
</template>
